# Archiwum: arkusze CKE z biologii w starszej formule (2015) — tryb „link + omówienie”.
# Materiały źródłowe zostają w oryginalnym PDF-ie CKE (link), w aplikacji są tylko: skrót polecenia,
# odpowiedź opracowana na podstawie zasad oceniania CKE (własnymi słowami) i omówienie IndexLab.
# Builder oznacza te arkusze jako archiwum: są do ćwiczeń, ale poza planem, prognozą i próbną maturą.
CKE15 = 'https://cke.gov.pl/images/_EGZAMIN_MATURALNY_OD_2015/Arkusze_egzaminacyjne'
Z1 = '1 pkt – odpowiedź poprawna (zgodna z zasadami oceniania CKE).\n0 pkt – odpowiedź niepoprawna, niepełna lub brak odpowiedzi.'
OPIS15 = ('Starsza formuła egzaminu (2015). Większość zadań pasuje do matury 2027, ale część zakresu '
          'i sposób punktowania mogą się różnić.')


def W(nr, strona, tytul, dzial, *zadania):
    return {'nr': nr, 'strona': strona, 'tytul': tytul,
            'zadania': [dict(z, dzialy=[dzial]) for z in zadania]}


def Z(nr, pkt, polecenie, odpowiedz, omowienie, zasady=None):
    return {'nr': nr, 'punkty': pkt, 'polecenie': polecenie, 'odpowiedz': odpowiedz,
            'zasady': zasady if zasady is not None else (Z1 if pkt == 1 else ''), 'omowienie': omowienie}


